from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'submission';OUT.mkdir(exist_ok=True)
B=ROOT/'B_delivery/results/task1_rerun_20261012';C=ROOT/'C_delivery/results/C_v1_20261012'
