 page();h(f'Appendix: {year} complete development metrics')
 data=[r for r in rows(C/'development_metrics.csv') if int(r['year'])==year]
 t(['Model','mm','Event rate','Brier','Log loss','PR-AUC','ROC-AUC'],[[{'frequency_baseline':'Baseline','logistic_regression':'LR','decision_tree':'Tree'}[r['model']],f"{float(r['threshold_mm']):g}",fmt(r['positive_rate']),fmt(r['brier']),fmt(r['log_loss']),fmt(r['pr_auc']),fmt(r['roc_auc'])] for r in data])
 p('All three candidates use the same supported full evaluation anchors: '+num(data[0]['n'])+' per threshold. Approximate AUC uses Spark numBins=1000. The main selection rule remains equal-threshold/equal-year Brier.')
