from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
font=os.environ.get('C_FONT_PATH','/System/Library/Fonts/STHeiti Light.ttc')
pdfmetrics.registerFont(TTFont('ReportBody',font,subfontIndex=0 if 'C_FONT_PATH' in os.environ else 1))
body=ParagraphStyle('body',fontName='ReportBody',fontSize=9.5,leading=13,spaceAfter=7)
heading=ParagraphStyle('heading',parent=body,fontSize=15,leading=20,spaceAfter=12,keepWithNext=True,textColor=colors.HexColor('#087f8c'))
cell=ParagraphStyle('cell',parent=body,fontSize=8,leading=11,spaceAfter=0)
caption=ParagraphStyle('caption',parent=body,fontSize=8.5,leading=12,textColor=colors.HexColor('#53616d'),spaceAfter=10)
story=[]
def para(s,style=body):return Paragraph(html.escape(str(s)),style)
story +=[Spacer(1,55),para('Singapore rainfall patterns and 30-minute exceedance prediction',ParagraphStyle('title',parent=heading,fontSize=25,leading=33)),Spacer(1,16),para('DSA5208 Project 2 | 2017-2024'),para('12 October 2026'),Spacer(1,20),para('Group members',heading)]
if complete:
 for m in members:story.append(para(m['name']+' | Student ID: '+m['student_id']))
else:story +=[para('MEMBER DETAILS PENDING',heading),para('The required names and student IDs must be supplied before this report is submitted to Canvas.')]
story +=[Spacer(1,25),para('Abstract',heading),para('Spark processing retains 48.54 million observations from eight annual rainfall exports, with explicit missingness, alignment and exact future-window semantics. Coverage-aware analysis distinguishes descriptive seasonality from valid fixed-station interannual comparisons. Three expanding temporal validation folds select a depth-5 decision tree. Its locked 2024 mean Brier is 0.017736, improving on the training-frequency baseline by 38.59%. The model, full source, fixed experiment configuration and reproduction evidence are delivered with a documented retrospective inference scope.'),Spacer(1,20),para('Data v1 / rainfall_v1_r3; B_v2 features; C_v1_20261012 model',caption)]
for b in blocks:
 kind=b['type']
 if kind=='pagebreak':story.append(PageBreak())
 elif kind=='heading':story.append(para(b['text'],heading))
 elif kind=='paragraph':story.append(para(b['text']))
 elif kind=='figure':
  story.append(Image(str(OUT/b['path']),width=495,height=b['height'],kind='proportional'));story.append(Spacer(1,4));story.append(para(b['caption'],caption))
 else:
  width=495/len(b['headers']);content=[[para(x,cell) for x in row] for row in [b['headers']]+b['rows']]
  tab=Table(content,colWidths=[width]*len(b['headers']),repeatRows=1,hAlign='LEFT');tab.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e5f1f2')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f7f9fa')]),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#087f8c'))]));story.extend([tab,Spacer(1,8)])
