 canvas.setFont('ReportBody',8);canvas.setFillColor(colors.HexColor('#697580'));canvas.drawString(40,22,'DSA5208 Project 2 | Singapore rainfall | 2017-2024');canvas.drawRightString(A4[0]-40,22,str(doc.page))
